import subprocess, os, re
env=dict(os.environ); env["PATH"]="/tmp/bin:"+env["PATH"]
cfg = """font pango:Fira Mono 8
bar {
  colors {
    separator #{sep}
    background #{bg}
    statusline #{st}
    focused_workspace #{a} #{b} #{c}
    active_workspace #{d} #{e} #{f}
    inactive_workspace #{g} #{h} #{i}
    urgent_workspace #{j} #{k} #{l}
  }
}
client.focused #{m} #{n} #{o} #{p}
client.focused_inactive #{q} #{r} #{s} #{t}
client.unfocused #{u} #{v} #{w} #{x}
client.urgent #{y} #{z} #{aa} #{ab}
