import itertools
CSS=[(n,hx(h)) for n,h in DB]
def mcss(x):
    return min(sum((x[i]-a[i])**2 for i in range(3)) for n,a in CSS)
def classify(cands, queries):
    # returns dict name -> list of queries in that candidate's cell
    out={c:[] for c in cands}
    for x in queries:
        mc=mcss(x)
        for c in cands:
            d=sum((x[i]-c[i])**2 for i in range(3))
            if d<=mc: out[c].append(x)
