exec(open("/tmp/t/disc.py").read())
import random, json, itertools, math
CSS=[(n,hx(h)) for n,h in DB]
def mcss(x):
    return min(sum((x[i]-a[i])**2 for i in range(3)) for n,a in CSS)
def solve_entry(name, samples, verbose=True):
    # samples: list of (x_tuple, toolname)
    inn=[]; out=[]
    for x,t in samples:
        if t.split('-')[0]==name: inn.append(x)
        elif mcss(x) is not None: out.append(x)
    # constraints
    cons=[]
    for x in inn: cons.append((x, mcss(x), True))
    for x in out: cons.append((x, mcss(x)+1, False))
    # bounding box from in-cell
    best=None
    # choose the tightest in-cell constraint for the box
    if not inn: return []
    inn_sorted=sorted(inn, key=lambda x: mcss(x))
    x0=inn_sorted[0]; r0=mcss(x0)
    box=[]
    for i in range(3):
        lo=max(0,x0[i]-int(math.sqrt(r0))+ -1); hi=min(255,x0[i]+int(math.sqrt(r0))+1)
        box.append(range(lo,hi+1))
    sols=[]
    for a in itertools.product(*box):
        ok=True
        for x,r,isIn in cons:
            d=sum((a[i]-x[i])**2 for i in range(3))
            if isIn:
                if d>r: ok=False;break
            else:
                if d<r: ok=False;break
        if ok: sols.append(a)
    return sols
