exec(open("/tmp/t/plane.py").read())
import random, itertools, math, json
random.seed(77)
qs=["#%02X%02X%02X"%(random.randrange(256),random.randrange(256),random.randrange(256)) for _ in range(40000)]
data=[]
for h,ns in probe(qs):
    if ns: data.append((hx(h), strip(ns[0])))
json.dump([[list(x),t] for x,t in data], open("/tmp/t/big.json","w"))
CSSVAL={n:hx(h) for n,h in DB}
def dd(a,x): return sum((a[i]-x[i])**2 for i in range(3))
def solve_entry(name):
    inn=[];out=[]
    for x,t in data:
        if t==name: inn.append(x)
        elif t in CSSVAL: out.append((x,CSSVAL[t]))
    if not inn: return []
    cons=[(x, min(dd(a,x) for n,a in CSSVAL.items()), True) for x in inn]
    cons+=[(x, dd(j,x)+1, False) for x,j in out]
    x0=min(inn,key=lambda x: min(dd(a,x) for n,a in CSSVAL.items()))
    r0=min(dd(a,x0) for n,a in CSSVAL.items())
    box=[]
    for i in range(3):
        lo=max(0,x0[i]-int(math.sqrt(r0))-1); hi=min(255,x0[i]+int(math.sqrt(r0))+1)
        box.append(range(lo,hi+1))
    sols=[]
    for a in itertools.product(*box):
        ok=True
        for x,r,isIn in cons:
            d=dd(a,x)
            if isIn:
                if d>r: ok=False;break
            else:
                if d<r: ok=False;break
        if ok: sols.append(a)
    return sols, len(inn), len(out)
for name in ['gray','lightslategray','lightgoldenrodyellow']:
    s,ni,no=solve_entry(name)
    print(name, "in-cell",ni,"out",no,"feasible",len(s), s[:20])
