    # box from two tightest
    srt=sorted(lt,key=lambda t: dd(t[1],t[0]))[:2]
    lo=[];hi=[]
    for i in range(3):
        vs=[t[0][i] for t in srt]
        lo.append(max(0,min(vs)-int(math.sqrt(r0))-2)); hi.append(min(255,max(vs)+int(math.sqrt(r0))+2))
    sols=[]
    for a in itertools.product(*[range(lo[i],hi[i]+1) for i in range(3)]):
        ok=True
        for x,r,isIn in cons:
            d=dd(a,x)
            if isIn:
                if d>r: ok=False;break
