    l=[lin(v) for v in rgb]
    X=0.4124564*l[0]+0.3575761*l[1]+0.1804375*l[2]
    Y=0.2126729*l[0]+0.7151522*l[1]+0.0721750*l[2]
    Z=0.0193339*l[0]+0.1191920*l[1]+0.9503041*l[2]
    return (X,Y,Z)
