    return v/12.92 if v<=0.04045 else ((v+0.055)/1.055)**2.4
def lab(rgb):
    l=[f(c) for c in rgb]
    X=0.4124564*l[0]+0.3575761*l[1]+0.1804375*l[2]
    Y=0.2126729*l[0]+0.7151522*l[1]+0.0721750*l[2]
    Z=0.0193339*l[0]+0.1191920*l[1]+0.9503041*l[2]
    Xn,Yn,Zn=0.95047,1.0,1.08883
    def g(t): return t**(1/3) if t>0.008856 else (7.787*t+16/116)
    fx,gY,fz=g(X/Xn),g(Y/Yn),g(Z/Zn)
    return (116*gY-16, 500*(fx-gY), 200*(gY-fz))
def m_lab(x,a):
    x1=lab(x); a1=lab(a)
    return sum((x1[i]-a1[i])**2 for i in range(3))
test(m_euc,"rgb euclid")
test(m_w,"weighted 2/4/3")
test(m_lin,"linear rgb")
test(m_xyz,"xyz")
test(m_lab,"lab")
