{"command": "cd /tmp/t && timeout 170 python3 - <<'PY'
exec(open("/tmp/t/model.py").read())
data=load_dense(4)
items=[(n,a) for n,a in CSSVAL.items()]
def dd(a,x): return sum((a[i]-x[i])**2 for i in range(3))
cons=set()
for x,t in data:
    ds=sorted(((dd(a,x),n) for n,a in items))
    mn=ds[0][0]
    tl=[n for v,n in ds if v==mn]
    if len(tl)>1 and t in tl:
        for o in tl:
            if o!=t: cons.add((t,o))
# topological sort: winner before loser
nodes=sorted({n for c in cons for n in c} | {n for n,a in items})
succ={n:set() for n in nodes}; indeg={n:0 for n in nodes}
for w,l in cons:
    if l not in succ[w]: succ[w].add(l); indeg[l]+=1
order=[]
avail=sorted([n for n in nodes if indeg[n]==0])
while avail:
    n=avail.pop(0); order.append(n)
    for m in sorted(succ[n]):
        indeg[m]-=1
        if indeg[m]==0: avail.append(m); avail.sort()
print("order len",len(order),"of",len(nodes))
print("remaining (cycle):", [n for n in nodes if n not in order])
print(order)
