{"command": "cd /tmp/t && timeout 170 python3 - <<'PY'
exec(open("/tmp/t/model.py").read())
data=load_dense(4)
LSG=(119.0,136.0,153.0)
items=[(n,a) for n,a in CSSVAL.items() if n not in ('lightslategrey','lightslategray')]
items.append(('gray',(128.3334,128.3334,128.3334)))
pre=[]
for x,t in data:
    mo=min(sum((x[i]-v[i])**2 for i in range(3)) for n,v in items)
    pre.append((x,t,mo))
def dd(x,a): return sum((x[i]-a[i])**2 for i in range(3))
def viol(a):
    bad=0
    for x,t,mo in pre:
        d1=dd(x,a); d2=dd(x,LSG)
        if t=='lightslategray':
            if not (d1<=d2 and d1<=mo): bad+=1
        elif t=='lightslategrey':
            if not (d2<=d1 and d2<=mo): bad+=1
        else:
            w=min(d1,d2,mo)
            if mo>w: bad+=1
    return bad
best=None
import itertools
for dr in [x/20 for x in range(-6,7)]:
  for dg in [x/20 for x in range(-6,7)]:
    for db in [x/20 for x in range(-6,7)]:
        a=(119.0+dr,136.0+dg,153.0+db)
        b=viol(a)
        if best is None or b<best[0]: best=(b,a)
print("best",best)
# refine around best
b0,a0=best
best2=None
for dr in [x/100 for x in range(-15,16)]:
  for dg in [x/100 for x in range(-15,16)]:
    for db in [x/100 for x in range(-15,16)]:
        a=(a0[0]+dr,a0[1]+dg,a0[2]+db)
        v=viol(a)
        if best2 is None or v<best2[0]: best2=(v,a)
print("refined",best2)
