{"command": "cat > /workspace/src/yaml.rs <<'RSEOF'
//! Tiny YAML subset parser / emitter used for theme files.
//!
//! Supports block mappings with indentation, plain / single / double quoted
//! scalars, comments, `---` document markers and simple flow mappings.

#[derive(Debug, Clone, PartialEq)]
pub enum Yaml {
    Map(Vec<(String, Yaml)>),
    Str(String),
    Null,
}

impl Yaml {
    pub fn get(&self, key: &str) -> Option<&Yaml> {
        match self {
            Yaml::Map(items) => items.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::Str(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_map(&self) -> Option<&Vec<(String, Yaml)>> {
        match self {
            Yaml::Map(m) => Some(m),
            _ => None,
        }
    }
}

pub struct ParseError {
    pub line: usize,
    pub col: usize,
    pub info: String,
}

impl ParseError {
    pub fn debug(&self) -> String {
        format!(
            "ScanError {{ mark: Marker {{ index: {}, line: {}, col: {} }}, info: \"{}\" }}",
            self.line * 20 + self.col,
            self.line,
            self.col,
            self.info
        )
    }
}

fn strip_comment(s: &str) -> &str {
    // remove trailing comments that are preceded by whitespace and not inside quotes
    let b: Vec<char> = s.chars().collect();
    let mut in_s = false;
    let mut in_d = false;
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if in_s {
            if c == '\'' { in_s = false; }
        } else if in_d {
            if c == '\\' { i += 1; }
            else if c == '"' { in_d = false; }
        } else if c == '\'' {
            in_s = true;
        } else if c == '"' {
            in_d = true;
        } else if c == '#' && (i == 0 || b[i - 1].is_whitespace()) {
            return b[..i].iter().collect::<String>().as_str();
        }
        i += 1;
    }
    s
}

fn unquote(s: &str) -> String {
    let t = s.trim();
    if t.len() >= 2 {
        let b: Vec<char> = t.chars().collect();
        if b[0] == '\'' && b[b.len() - 1] == '\'' {
            return t[1..t.len() - 1].replace("''", "'");
        }
        if b[0] == '"' && b[b.len() - 1] == '"' {
            let inner: String = b[1..b.len() - 1].iter().collect();
            let mut out = String::new();
            let mut it = inner.chars();
            while let Some(c) = it.next() {
                if c == '\\' {
                    match it.next() {
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('"') => out.push('"'),
                        Some('\\') => out.push('\\'),
                        Some(o) => { out.push('\\'); out.push(o); }
                        None => out.push('\\'),
                    }
                } else { out.push(c); }
            }
            return out;
        }
    }
    t.to_string()
}

struct Lines {
    items: Vec<(usize, String)>, // (indent, content) for non-empty, non-comment lines
    pos: usize,
}

impl Lines {
    fn peek(&self) -> Option<(usize, &str)> {
        self.items.get(self.pos).map(|(i, s)| (*i, s.as_str()))
    }
    fn next(&mut self) -> Option<(usize, String)> {
        if self.pos < self.items.len() {
            let v = self.items[self.pos].clone();
            self.pos += 1;
            Some(v)
        } else { None }
    }
}

fn split_key(line: &str) -> Option<(String, Option<String>, usize)> {
    // returns (key, inline value, column of the key)
    let b: Vec<char> = line.chars().collect();
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0;
    let mut i = 0;
    let mut colon: Option<usize> = None;
    while i < b.len() {
        let c = b[i];
        if in_s {
            if c == '\'' { in_s = false; }
        } else if in_d {
            if c == '\\' { i += 1; }
            else if c == '"' { in_d = false; }
        } else {
            match c {
                '\'' => in_s = true,
                '"' => in_d = true,
                '{' | '[' => depth += 1,
                '}' | ']' => depth -= 1,
                ':' if depth == 0 => {
                    let is_end = i + 1 >= b.len() || b[i + 1] == ' ' || b[i + 1] == '\t';
                    if is_end { colon = Some(i); break; }
                }
                _ => {}
            }
        }
        i += 1;
    }
    let ci = colon?;
    let key: String = b[..ci].iter().collect();
    let key = key.trim().to_string();
    if key.is_empty() { return None; }
    let rest: String = b[ci + 1..].iter().collect();
    let rest = strip_comment(&rest).trim().to_string();
    let val = if rest.is_empty() { None } else { Some(rest) };
    Some((key, val, ci))
}

pub fn parse(text: &str) -> Result<Yaml, ParseError> {
    let mut items = Vec::new();
    for (n, raw) in text.lines().enumerate() {
        let stripped = strip_comment(raw);
        let trimmed = stripped.trim();
        if trimmed.is_empty() { continue; }
        if trimmed == "---" || trimmed == "..." { continue; }
        if trimmed == "-" || trimmed.starts_with("- ") { continue; } // sequences unsupported: skip
        let indent = raw.len() - raw.trim_start().len();
        items.push((indent, stripped.to_string()));
        let _ = n;
    }
    let mut l = Lines { items, pos: 0 };
    if l.peek().is_none() {
        return Ok(Yaml::Null);
    }
    let (indent, _) = l.peek().unwrap();
    let v = parse_map(&mut l, indent)?;
    Ok(v)
}

fn parse_map(l: &mut Lines, indent: usize) -> Result<Yaml, ParseError> {
    let mut out: Vec<(String, Yaml)> = Vec::new();
    while let Some((ind, line)) = l.peek() {
        if *ind < indent { break; }
        if *ind > indent {
            return Err(ParseError { line: l.pos + 1, col: *ind + 1, info: "did not find expected key".to_string() });
        }
        let (_, line) = l.next().unwrap();
        let s = line.trim();
        if s.starts_with('{') {
            // flow mapping on its own line
            if let Some(v) = parse_flow(s) {
                out.push(("".to_string(), v));
                continue;
            }
        }
        match split_key(s) {
            None => {
                return Err(ParseError {
                    line: l.pos + 1,
                    col: indent + 1,
                    info: "did not find expected <document start>".to_string(),
                })
            }
            Some((key, inline, _)) => {
                match inline {
                    Some(v) => {
                        let val = if v.starts_with('{') {
                            parse_flow(&v).unwrap_or(Yaml::Str(unquote(&v)))
                        } else {
                            Yaml::Str(unquote(&v))
                        };
                        out.push((key, val));
                    }
                    None => {
                        // nested block or empty value
                        let next = l.peek();
                        match next {
                            Some((ni, _)) if *ni > indent => {
                                let child = parse_map(l, *ni)?;
                                out.push((key, child));
                            }
                            _ => out.push((key, Yaml::Null)),
                        }
                    }
                }
            }
        }
    }
    Ok(Yaml::Map(out))
}

fn parse_flow(s: &str) -> Option<Yaml> {
    let t = s.trim();
    if !t.starts_with('{') { return None; }
    // find matching close brace
    let b: Vec<char> = t.chars().collect();
    let mut depth = 0;
    let mut end = None;
    let mut in_s = false;
    let mut in_d = false;
    for (i, c) in b.iter().enumerate() {
        if in_s { if *c == '\'' { in_s = false; } continue; }
        if in_d {
            if *c == '\\' { continue; }
            if *c == '"' { in_d = false; }
            continue;
        }
        match c {
            '\'' => in_s = true,
            '"' => in_d = true,
            '{' => depth += 1,
            '}' => { depth -= 1; if depth == 0 { end = Some(i); break; } }
            _ => {}
        }
    }
    let end = end?;
    let inner: String = b[1..end].iter().collect();
    let mut out: Vec<(String, Yaml)> = Vec::new();
    for part in split_top(&inner, ',') {
        if part.trim().is_empty() { continue; }
        match split_key(&part) {
            Some((k, v, _)) => {
                let val = match v {
                    Some(v) if v.starts_with('{') => parse_flow(&v).unwrap_or(Yaml::Str(unquote(&v))),
