    let first = s.chars().next().unwrap();
    if "#{}[]&*!|>'\"%@`".contains(first) { return true; }
    if " \t".contains(first) || s.ends_with(' ') { return true; }
    if s.contains(": ") || s.ends_with(':') || s.contains(" #") { return true; }
    // looks like a number / bool / null
    if s == "~" || s == "null" || s == "true" || s == "false" || s == "yes" || s == "no"
        || s == "on" || s == "off" || s == "y" || s == "n" {
        return true;
    }
    let t = s.trim_start_matches(['-', '+']);
    if t.is_empty() { return false; }
    let body = t.trim_start_matches('.');
    if !body.is_empty() && body.chars().all(|c| c.is_ascii_digit()) && body.chars().any(|c| c.is_ascii_digit()) {
        return true;
    }
    if let Some(rest) = s.strip_prefix("0x") {
        if !rest.is_empty() && rest.chars().all(|c| c.is_ascii_hexdigit()) { return true; }
    }
    false
}
