//! Colour naming: reproduces the behaviour of the `colornamer` crate.

use crate::db::DB;

#[derive(Debug, Clone, PartialEq)]
pub struct Color {
    pub r: f64,
    pub g: f64,
    pub b: f64,
}

/// Panics like the original crate when the hex string cannot be parsed.
pub fn parse_hex(input: &str) -> Color {
    let s: String = input.chars().map(|c| c.to_ascii_uppercase()).collect();
    let hex = if s.starts_with('#') { &s[1..] } else { &s.as_str()[..] };
    if hex.len() != 6 && hex.len() != 8 {
        panic!("got invalid hex string: \"{}\"", s);
    }
    let n = hex.len();
    let mut vals = [0f64; 4];
    for i in 0..4 {
        if i * 2 + 1 >= n {
            break;
        }
        let sub = &hex[i * 2..i * 2 + 2];
        match u8::from_str_radix(sub, 16) {
            Ok(v) => vals[i] = v as f64,
            Err(_) => panic!("got invalid hex string: \"{}\"", s),
        }
    }
    Color { r: vals[0], g: vals[1], b: vals[2] }
}

/// Returns the name of the closest colour in the database (ties broken by the
/// database order).
pub fn name(c: &Color) -> &'static str {
    let mut best: Option<(f64, &'static str)> = None;
    for (n, r, g, b) in DB.iter() {
        let dr = c.r - r;
        let dg = c.g - g;
        let db = c.b - b;
        let d = dr * dr + dg * dg + db * db;
        match best {
            Some((bd, _)) if d >= bd => {}
            _ => best = Some((d, n)),
        }
    }
    best.map(|(_, n)| n).unwrap_or("black")
}

/// Formats a colour channel value the way the original writes hex values into
/// i3 config files (integer, no leading "#").
pub fn to_hex(c: &Color) -> String {
    format!("#{:02X}{:02X}{:02X}", c.r.round() as i32 & 0xff, c.g.round() as i32 & 0xff, c.b.round() as i32 & 0xff)
}
