//! Theme model, loading and `--to-theme` generation.

use crate::yaml::{self, Yaml};

#[derive(Debug, Clone, Default)]
pub struct WorkspaceColors {
    pub border: Option<String>,
    pub background: Option<String>,
    pub text: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct WindowColors {
    pub border: Option<String>,
    pub background: Option<String>,
    pub text: Option<String>,
    pub indicator: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct BarColors {
    pub background: Option<String>,
    pub statusline: Option<String>,
    pub separator: Option<String>,
    pub focused_workspace: Option<WorkspaceColors>,
    pub active_workspace: Option<WorkspaceColors>,
    pub inactive_workspace: Option<WorkspaceColors>,
    pub urgent_workspace: Option<WorkspaceColors>,
}

#[derive(Debug, Clone, Default)]
pub struct Theme {
    pub description: String,
    pub colors: Vec<(String, String)>,
    pub focused: Option<WindowColors>,
    pub focused_inactive: Option<WindowColors>,
    pub unfocused: Option<WindowColors>,
    pub urgent: Option<WindowColors>,
    pub bar: BarColors,
}

fn ws_from(v: &Yaml) -> WorkspaceColors {
    let g = |k: &str| v.get(k).and_then(|x| x.as_str()).map(|s| s.to_string());
    WorkspaceColors { border: g("border"), background: g("background"), text: g("text") }
}

fn win_from(v: &Yaml) -> WindowColors {
    let g = |k: &str| v.get(k).and_then(|x| x.as_str()).map(|s| s.to_string());
    WindowColors {
        border: g("border"),
        background: g("background"),
        text: g("text"),
        indicator: g("indicator"),
    }
}

impl Theme {
    pub fn from_yaml(doc: &Yaml) -> Theme {
        let mut t = Theme::default();
        if let Yaml::Null = doc {
            return t;
        }
        if let Some(meta) = doc.get("meta") {
            if let Some(d) = meta.get("description").and_then(|x| x.as_str()) {
                t.description = d.to_string();
            }
        }
        if let Some(colors) = doc.get("colors").and_then(|c| c.as_map()) {
            for (k, v) in colors {
                if let Some(s) = v.as_str() {
                    t.colors.push((k.clone(), s.to_string()));
                }
            }
        }
        if let Some(w) = doc.get("window_colors") {
            t.focused = w.get("focused").map(win_from);
            t.focused_inactive = w.get("focused_inactive").map(win_from);
            t.unfocused = w.get("unfocused").map(win_from);
            t.urgent = w.get("urgent").map(win_from);
        }
        if let Some(b) = doc.get("bar_colors") {
            let g = |k: &str| b.get(k).and_then(|x| x.as_str()).map(|s| s.to_string());
            t.bar.background = g("background");
            t.bar.statusline = g("statusline");
            t.bar.separator = g("separator");
            t.bar.focused_workspace = b.get("focused_workspace").map(ws_from);
            t.bar.active_workspace = b.get("active_workspace").map(ws_from);
            t.bar.inactive_workspace = b.get("inactive_workspace").map(ws_from);
            t.bar.urgent_workspace = b.get("urgent_workspace").map(ws_from);
        }
        t
    }

    /// resolves a colour reference through the `colors` map
    pub fn resolve(&self, name: &str) -> String {
        for (k, v) in self.colors.iter() {
            if k == name {
                return v.clone();
            }
        }
        name.to_string()
    }

    pub fn to_yaml(&self) -> String {
        let mut s = String::from("---\nmeta:\n");
        s.push_str("  description: ");
        s.push_str(&quote_if_needed(&self.description));
        s.push('\n');
        s.push_str("colors:\n");
        for (k, v) in self.colors.iter() {
            s.push_str("  ");
            s.push_str(&quote_if_needed(k));
            s.push_str(": ");
            s.push_str(&quote_if_needed(v));
            s.push('\n');
        }
        s.push_str("window_colors:\n");
        for (key, w) in [
            ("focused", &self.focused),
            ("focused_inactive", &self.focused_inactive),
            ("unfocused", &self.unfocused),
            ("urgent", &self.urgent),
        ] {
            if let Some(w) = w {
                s.push_str("  ");
                s.push_str(key);
                s.push_str(":\n");
                for (k, v) in [("border", &w.border), ("background", &w.background), ("text", &w.text), ("indicator", &w.indicator)] {
                    if let Some(v) = v {
                        s.push_str("    ");
                        s.push_str(k);
                        s.push_str(": ");
                        s.push_str(&quote_if_needed(v));
                        s.push('\n');
                    }
                }
            }
        }
        s.push_str("bar_colors:\n");
        for (k, v) in [("background", &self.bar.background), ("statusline", &self.bar.statusline), ("separator", &self.bar.separator)] {
            if let Some(v) = v {
                s.push_str("  ");
                s.push_str(k);
                s.push_str(": ");
                s.push_str(&quote_if_needed(v));
                s.push('\n');
            }
        }
        for (k, w) in [
            ("focused_workspace", &self.bar.focused_workspace),
            ("active_workspace", &self.bar.active_workspace),
            ("inactive_workspace", &self.bar.inactive_workspace),
            ("urgent_workspace", &self.bar.urgent_workspace),
        ] {
            if let Some(w) = w {
                s.push_str("  ");
                s.push_str(k);
                s.push_str(":\n");
                for (kk, v) in [("border", &w.border), ("background", &w.background), ("text", &w.text)] {
                    if let Some(v) = v {
                        s.push_str("    ");
                        s.push_str(kk);
                        s.push_str(": ");
                        s.push_str(&quote_if_needed(v));
                        s.push('\n');
                    }
                }
            }
        }
        s
    }
}

pub fn quote_if_needed(s: &str) -> String {
    if yaml::needs_quotes(s) {
        let mut out = String::from("\"");
        for c in s.chars() {
            match c {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                _ => out.push(c),
            }
        }
        out.push('"');
        out
    } else {
        s.to_string()
    }
}
