//! Reading and rewriting i3 configuration files.

use crate::theme::Theme;

pub const BAR_DIRECTIVES: [&str; 7] = [
    "separator",
    "background",
    "statusline",
    "focused_workspace",
    "active_workspace",
    "inactive_workspace",
