    "client.focused",
    "client.focused_inactive",
    "client.unfocused",
    "client.urgent",
];

fn indent_of(line: &str) -> String {
    let mut s = String::new();
    for c in line.chars() {
        if c == ' ' || c == '\t' {
            s.push(c);
        } else {
            break;
        }
    }
    s
}

fn first_token(line: &str) -> &str {
    line.split_whitespace().next().unwrap_or("")
}

fn replace_ws_line(orig: &str, indent: &str, key: &str, vals: &[&str]) -> String {
    let parts: Vec<&str> = orig.split_whitespace().collect();
    let mut out = format!("{}{}", indent, key);
    for v in vals {
        out.push(' ');
        out.push_str(v);
    }
    if parts.len() > 3 {
        out.push(' ');
        out.push_str(parts[3]);
    }
    out
}

fn replace_single_line(indent: &str, key: &str, val: &str) -> String {
    format!("{}{} {}", indent, key, val)
}

fn bar_entry(key: &str, vals: &[&str], indent: &str) -> String {
    let mut out = format!("{}{}", indent, key);
    for v in vals {
        out.push(' ');
        out.push_str(v);
    }
    out
}

/// Applies `theme` to `content`, returning the new configuration.
pub fn apply(content: &str, theme: &Theme) -> String {
    let mut out: Vec<String> = Vec::new();
    let mut in_bar = false;
    let mut in_colors = false;
    let mut colors_block_emitted = false;
    let mut found: [bool; 4] = [false; 4];

    for line in content.lines() {
        let tok = first_token(line).to_string();
        if !in_bar {
            if tok == "bar" {
                in_bar = true;
                colors_block_emitted = false;
                out.push(line.to_string());
                continue;
            }
            if let Some(i) = CLIENT_KEYS.iter().position(|k| *k == tok) {
                if let Some(w) = window_colors(theme, i) {
                    found[i] = true;
                    out.push(format!(
                        "{} {} {} {}",
                        tok, w.0, w.1, w.2, w.3
                    ));
                    continue;
                }
            }
            out.push(line.to_string());
            continue;
        }
        // inside a bar block
        if in_colors {
            let trimmed = line.trim();
            if tok == "}" {
                let ind = indent_of(line);
                let dbl = format!("{}{}", ind, ind);
                for key in BAR_DIRECTIVES.iter() {
                    if let Some(vals) = bar_values(theme, key) {
                        if !already_present(&out, key) {
                            out.push(bar_entry(key, &vals, &dbl));
                        }
                    }
                }
                in_colors = false;
                out.push(line.to_string());
                continue;
            }
            if BAR_DIRECTIVES.contains(&tok.as_str()) {
                let ind = indent_of(line);
                if let Some(v) = theme_bar(theme, &tok) {
                    match v {
                        BarVal::Single(s) => out.push(replace_single_line(&ind, &tok, &s)),
                        BarVal::Triple(v3) => out.push(replace_ws_line(line, &ind, &tok, &v3)),
                    }
                    continue;
                }
                out.push(line.to_string());
                continue;
            }
            if trimmed.is_empty() || trimmed.starts_with('#') {
                out.push(line.to_string());
                continue;
            }
            // unknown directive inside colors block: dropped
            continue;
        }
        // inside bar, not inside colors
        if tok == "colors" {
            in_colors = true;
            out.push(line.to_string());
            continue;
        }
        if tok == "}" {
            if !colors_block_emitted && theme_has_bar_colors(theme) {
                out.push("  colors {".to_string());
                for key in BAR_DIRECTIVES.iter() {
                    if let Some(vals) = bar_values(theme, key) {
                        out.push(bar_entry(key, &vals, "    "));
                    }
                }
                out.push("  }".to_string());
                colors_block_emitted = true;
            }
            in_bar = false;
            out.push(line.to_string());
            continue;
        }
        out.push(line.to_string());
    }

    // append missing client lines
    for i in 0..4 {
        if found[i] { continue; }
        if let Some(w) = window_colors(theme, i) {
            out.push(format!("{} {} {} {}", CLIENT_KEYS[i], w.0, w.1, w.2, w.3));
        }
    }
    let mut s = out.join("\n");
    s.push('\n');
    s
}

enum BarVal {
    Single(String),
    Triple(Vec<&'static str>),
}

fn theme_bar<'a>(theme: &'a Theme, key: &str) -> Option<BarVal> {
    let b = &theme.bar;
    let ws = match key {
        "focused_workspace" => b.focused_workspace.as_ref(),
        "active_workspace" => b.active_workspace.as_ref(),
        "inactive_workspace" => b.inactive_workspace.as_ref(),
        "urgent_workspace" => b.urgent_workspace.as_ref(),
        _ => None,
    };
    if let Some(w) = ws {
        let (a, c, d) = (w.border.as_ref()?, w.background.as_ref()?, w.text.as_ref()?);
        let a = theme.resolve(a);
        let c = theme.resolve(c);
        let d = theme.resolve(d);
        return Some(BarVal::Triple(vec![leak(a), leak(c), leak(d)]));
    }
    match key {
        "separator" => b.separator.as_ref().map(|s| BarVal::Single(theme.resolve(s))),
        "background" => b.background.as_ref().map(|s| BarVal::Single(theme.resolve(s))),
        "statusline" => b.statusline.as_ref().map(|s| BarVal::Single(theme.resolve(s))),
        _ => None,
    }
}

thread_local! {
    static SCRATCH: Vec<String> = Vec::new();
}

fn leak(s: String) -> &'static str {
    SCRATCH.with(|v| {
        let mut v = v.borrow_mut();
        v.push(s);
        unsafe { std::mem::transmute::<&str, &'static str>(v.last().unwrap().as_str()) }
    })
}

fn bar_values(theme: &Theme, key: &str) -> Option<Vec<String>> {
    match theme_bar(theme, key) {
        Some(BarVal::Single(s)) => Some(vec![s]),
        Some(BarVal::Triple(v)) => Some(v.into_iter().map(|s| s.to_string()).collect()),
        None => None,
    }
}

fn theme_has_bar_colors(theme: &Theme) -> bool {
    theme.bar.background.is_some()
        || theme.bar.statusline.is_some()
        || theme.bar.separator.is_some()
        || theme.bar.focused_workspace.is_some()
        || theme.bar.active_workspace.is_some()
        || theme.bar.inactive_workspace.is_some()
        || theme.bar.urgent_workspace.is_some()
}

fn already_present(out: &[String], key: &str) -> bool {
    out.iter().any(|l| first_token(l) == key)
}

fn window_colors(theme: &Theme, i: usize) -> Option<(String, String, String, String)> {
    let w = match i {
        0 => theme.focused.as_ref()?,
        1 => theme.focused_inactive.as_ref()?,
        2 => theme.unfocused.as_ref()?,
        _ => theme.urgent.as_ref()?,
    };
    let b = w.border.as_ref()?;
    let bg = w.background.as_ref()?;
    let t = w.text.as_ref()?;
    let ind = w.indicator.as_ref()?;
    Some((
        theme.resolve(b),
        theme.resolve(bg),
        theme.resolve(t),
        theme.resolve(ind),
    ))
}
