                let dbl = format!("{}{}", ind, ind);
                for key in BAR_DIRECTIVES.iter() {
                    if colors_seen.contains(key) { continue; }
                    if let Some(vals) = bar_values(theme, key) {
                        out.push(bar_entry(key, &vals, &dbl));
                    }
                }
                colors_seen.clear();
                in_colors = false;
                out.push(line.to_string());
                continue;
            }
            if BAR_DIRECTIVES.contains(&tok.as_str()) {
                let ind = indent_of(line);
                if !colors_seen.contains(&tok.as_str()) {
                    colors_seen.push(Box::leak(tok.clone().into_boxed_str()));
                }
                match theme_bar(theme, &tok) {
                    Some(BarVal::Single(s)) => out.push(replace_single_line(&ind, &tok, &s)),
                    Some(BarVal::Triple(v)) => out.push(replace_ws_line(line, &ind, &tok, &v)),
                    _ => out.push(line.to_string()),
                }
                continue;
            }
            if trimmed.is_empty() || trimmed.starts_with('#') {
                out.push(line.to_string());
                continue;
            }
            continue;
        }
        if tok == "colors" {
            in_colors = true;
            bar_has_colors = true;
            out.push(line.to_string());
            continue;
        }
        if tok == "}" {
            if theme_has_bar_colors(theme) && !bar_has_colors {
                out.push("  colors {".to_string());
                for key in BAR_DIRECTIVES.iter() {
                    if let Some(vals) = bar_values(theme, key) {
                        out.push(bar_entry(key, &vals, "    "));
                    }
                }
                out.push("  }".to_string());
                bar_has_colors = true;
            }
            in_bar = false;
            out.push(line.to_string());
            continue;
        }
        out.push(line.to_string());
    }

    for i in 0..4 {
        if found[i] { continue; }
        if let Some(w) = window_colors(theme, i) {
            out.push(format!("{} {} {} {}", CLIENT_KEYS[i], w[0], w[1], w[2], w[3]));
        }
    }
    let mut s = out.join("\n");
    s.push('\n');
    s
}
RSEOF
echo ok"}

