            }
            if name == "help" {
                return Outcome::Help;
            }
            if name == "version" {
                return Outcome::Version;
            }
            if takes_value(&name) {
                let val = match inline {
                    Some(v) => v,
                    None => {
                        if i + 1 < raw.len() && !is_flaglike(&raw[i + 1]) {
                            i += 1;
                            raw[i].clone()
                        } else {
                            match default_value(&name) {
                                Some(d) => d.to_string(),
                                None => {
                                    present.push(name.clone());
                                    return Outcome::Error(err(
                                        format!("The argument '--{} <file>' requires a value but none was supplied", name),
                                        &present.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
                                    ));
                                }
                            }
                        }
                    }
                };
                if !present.contains(&name) {
                    present.push(name.clone());
                }
                match name.as_str() {
                    "config" => args.config = Some(val),
                    "output" => args.output = Some(val),
                    "to-theme" => args.to_theme = Some(val),
                    _ => {}
                }
            } else {
                if !present.contains(&name) {
                    present.push(name.clone());
                }
                match name.as_str() {
                    "list-all" => args.list_all = true,
                    "reload" => args.reload = true,
                    "save" => args.save = true,
                    _ => {}
                }
            }
            i += 1;
            continue;
        }
        if a.len() > 1 && a.starts_with('-') {
            // short flag cluster
            let chars: Vec<char> = a.chars().skip(1).collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                let long = match c {
                    'h' => "help",
                    'l' => "list-all",
                    'r' => "reload",
                    's' => "save",
                    'V' => "version",
                    'c' => "config",
                    'o' => "output",
                    't' => "to-theme",
                    _ => return Outcome::Error(unknown_arg(&format!("-{}", c))),
                };
                if long == "help" {
                    return Outcome::Help;
                }
                if long == "version" {
                    return Outcome::Version;
                }
                if takes_value(long) {
                    // remainder of the cluster is the value, or the next arg
                    let rest: String = chars[ci + 1..].iter().collect();
                    let val = if !rest.is_empty() {
                        rest
                    } else if i + 1 < raw.len() && !is_flaglike(&raw[i + 1]) {
                        i += 1;
                        raw[i].clone()
                    } else {
                        match default_value(long) {
                            Some(d) => d.to_string(),
                            None => {
                                if !present.iter().any(|s| s == long) {
                                    present.push(long.to_string());
                                }
                                return Outcome::Error(err(
                                    format!("The argument '--{} <file>' requires a value but none was supplied", long),
                                    &present.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
                                ));
                            }
                        }
                    };
                    if !present.iter().any(|s| s == long) {
                        present.push(long.to_string());
                    }
                    match long {
                        "config" => args.config = Some(val),
                        "output" => args.output = Some(val),
                        "to-theme" => args.to_theme = Some(val),
                        _ => {}
                    }
                    ci = chars.len();
                    break;
                } else {
                    if !present.iter().any(|s| s == long) {
                        present.push(long.to_string());
                    }
                    match long {
                        "list-all" => args.list_all = true,
                        "reload" => args.reload = true,
                        "save" => args.save = true,
                        _ => {}
                    }
                    ci += 1;
                }
            }
            i += 1;
            continue;
        }
        // positional
        if args.theme.is_some() {
            return Outcome::Error(unknown_arg(&a));
        }
        args.theme = Some(a);
        i += 1;
    }
    Outcome::Run(args)
}

fn is_flaglike(s: &str) -> bool {
    s.len() > 1 && s.starts_with('-')
}
RSEOF
echo ok"}

