        rust_panic("src/main.rs:304:39", &unwrap_err(&e));
    }
}

fn load_theme(arg: &str) -> Theme {
    for (name, data, _) in THEMES.iter() {
        if *name == arg {
            let doc = yaml::parse(data).unwrap_or(Yaml::Null);
            return theme_from(doc, true);
        }
    }
    match std::fs::read_to_string(arg) {
        Err(e) => {
            eprintln!("Could not open theme: {} - {}", arg, e);
            eprintln!(" Use `i3-style --list-all` to see the available themes.");
