/// Extracts the colours used by the config and names them.
fn build_theme_from_config(content: &str) -> Theme {
    use std::collections::BTreeMap;
    let mut order: Vec<String> = Vec::new();
    let mut values: BTreeMap<String, String> = BTreeMap::new();
    let mut push = |v: String, order: &mut Vec<String>, values: &mut BTreeMap<String, String>| {
        if !values.contains_key(&v) {
            order.push(v.clone());
        }
        values.insert(v.clone(), v.clone());
    };

    // parse the config
    let mut bar: Vec<(String, Vec<String>)> = Vec::new();
    let mut last_bar: Option<Vec<(String, Vec<String>)>> = None;
    let mut clients: Vec<(String, Vec<String>)> = Vec::new();
    let mut in_bar = false;
    let mut in_colors = false;
    for line in content.lines() {
        let tok = line.split_whitespace().next().unwrap_or("");
        if !in_bar {
            if tok == "bar" {
                in_bar = true;
                bar.clear();
                continue;
            }
            if let Some(rest) = tok.strip_prefix("client.") {
                let vals: Vec<String> = line.split_whitespace().skip(1).map(|s| s.to_string()).collect();
                if !vals.is_empty() {
                    clients.retain(|(k, _)| k != &format!("client.{}", rest));
                    clients.push((format!("client.{}", rest), vals));
                }
            }
            continue;
        }
        if in_colors {
            if tok == "}" {
                in_colors = false;
                continue;
            }
            if config::BAR_DIRECTIVES.contains(&tok) {
                let vals: Vec<String> = line.split_whitespace().skip(1).map(|s| s.to_string()).collect();
                bar.retain(|(k, _)| k != tok);
                bar.push((tok.to_string(), vals));
            }
            continue;
        }
        if tok == "colors" {
            in_colors = true;
            continue;
        }
        if tok == "}" {
            in_bar = false;
            last_bar = Some(bar.clone());
            continue;
        }
    }
    if in_bar && !bar.is_empty() {
        last_bar = Some(bar.clone());
    }

    let get_bar = |key: &str| -> Option<Vec<String>> {
        let b = last_bar.as_ref()?;
        b.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
    };
    let get_client = |key: &str| -> Option<Vec<String>> {
        clients.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
    };

    // collect colours in the observed order
    for key in ["separator", "background", "statusline"] {
        if let Some(v) = get_bar(key) {
            if let Some(first) = v.first() {
                push(colors::to_hex(&colors::parse_hex(first)), &mut order, &mut values);
            }
        }
    }
    for key in ["focused_workspace", "inactive_workspace", "urgent_workspace"] {
        if let Some(v) = get_bar(key) {
            for x in v.iter().take(3) {
                push(colors::to_hex(&colors::parse_hex(x)), &mut order, &mut values);
            }
        }
    }
    for key in config::CLIENT_KEYS {
        if let Some(v) = get_client(key) {
            for x in v.iter().take(4) {
                push(colors::to_hex(&colors::parse_hex(x)), &mut order, &mut values);
            }
        }
    }

    // assign names
    let mut names: Vec<String> = Vec::new();
    let mut map: Vec<(String, String)> = Vec::new();
    for v in order.iter() {
        let base = colors::name(&colors::parse_hex(v));
        let mut candidate = base.to_string();
        let mut i = 1;
        while names.contains(&candidate) {
            candidate = format!("{}-{}", base, i);
            i += 1;
        }
        names.push(candidate.clone());
        map.push((candidate, v.clone()));
    }

    let mut t = Theme {
        description: "AUTOMATICALLY GENERATED THEME".to_string(),
        colors: map,
        ..Default::default()
    };
    let nm = |v: &String| -> String {
        let i = order.iter().position(|x| x == v).unwrap();
        names[i].clone()
    };
    if let Some(v) = get_bar("background") {
        if let Some(f) = v.first() {
            let h = colors::to_hex(&colors::parse_hex(f));
            t.bar.background = Some(nm(&h));
        }
    }
    if let Some(v) = get_bar("statusline") {
        if let Some(f) = v.first() {
            let h = colors::to_hex(&colors::parse_hex(f));
            t.bar.statusline = Some(nm(&h));
        }
    }
    if let Some(v) = get_bar("separator") {
        if let Some(f) = v.first() {
            let h = colors::to_hex(&colors::parse_hex(f));
            t.bar.separator = Some(nm(&h));
        }
    }
    for (key, slot) in [
        ("focused_workspace", 0usize),
        ("urgent_workspace", 1usize),
    ] {
        if let Some(v) = get_bar(key) {
            if v.len() >= 3 {
                let ws = theme::WorkspaceColors {
                    border: Some(nm(&colors::to_hex(&colors::parse_hex(&v[0])))),
                    background: Some(nm(&colors::to_hex(&colors::parse_hex(&v[1])))),
                    text: Some(nm(&colors::to_hex(&colors::parse_hex(&v[2])))),
                };
                match slot {
                    0 => t.bar.focused_workspace = Some(ws),
                    _ => t.bar.urgent_workspace = Some(ws),
                }
            }
        }
    }
    for (i, key) in config::CLIENT_KEYS.iter().enumerate() {
        if let Some(v) = get_client(key) {
            if v.len() >= 4 {
                let w = theme::WindowColors {
                    border: Some(nm(&colors::to_hex(&colors::parse_hex(&v[0])))),
                    background: Some(nm(&colors::to_hex(&colors::parse_hex(&v[1])))),
                    text: Some(nm(&colors::to_hex(&colors::parse_hex(&v[2])))),
                    indicator: Some(nm(&colors::to_hex(&colors::parse_hex(&v[3])))),
                };
                match i {
                    0 => t.focused = Some(w),
                    1 => t.focused_inactive = Some(w),
                    2 => t.unfocused = Some(w),
                    _ => t.urgent = Some(w),
                }
            }
        }
    }
    t
}
