                push(colors::to_hex(&colors::parse_hex(first)), &mut order, &mut values);
            }
        }
    }
    for key in ["focused_workspace", "inactive_workspace", "urgent_workspace"] {
        if let Some(v) = get_bar(key) {
            for x in v.iter().take(3) {
                push(colors::to_hex(&colors::parse_hex(x)), &mut order, &mut values);
            }
        }
    }
    for key in config::CLIENT_KEYS {
        if let Some(v) = get_client(key) {
            for x in v.iter().take(4) {
                push(colors::to_hex(&colors::parse_hex(x)), &mut order, &mut values);
            }
        }
    }

    // assign names
    let mut names: Vec<String> = Vec::new();
    let mut map: Vec<(String, String)> = Vec::new();
    for v in order.iter() {
        let base = colors::name(&colors::parse_hex(v));
        let mut candidate = base.to_string();
        let mut i = 1;
        while names.contains(&candidate) {
            candidate = format!("{}-{}", base, i);
            i += 1;
        }
        names.push(candidate.clone());
        map.push((candidate, v.clone()));
    }

    let mut t = Theme {
        description: "AUTOMATICALLY GENERATED THEME".to_string(),
        colors: map,
        ..Default::default()
    };
    let nm = |v: &String| -> String {
        let i = order.iter().position(|x| x == v).unwrap();
        names[i].clone()
    };
    if let Some(v) = get_bar("background") {
        if let Some(f) = v.first() {
            let h = colors::to_hex(&colors::parse_hex(f));
            t.bar.background = Some(nm(&h));
        }
    }
    if let Some(v) = get_bar("statusline") {
        if let Some(f) = v.first() {
            let h = colors::to_hex(&colors::parse_hex(f));
            t.bar.statusline = Some(nm(&h));
        }
    }
    if let Some(v) = get_bar("separator") {
        if let Some(f) = v.first() {
            let h = colors::to_hex(&colors::parse_hex(f));
            t.bar.separator = Some(nm(&h));
        }
    }
    for (key, slot) in [
        ("focused_workspace", 0usize),
        ("urgent_workspace", 1usize),
    ] {
        if let Some(v) = get_bar(key) {
            if v.len() >= 3 {
                let ws = theme::WorkspaceColors {
                    border: Some(nm(&colors::to_hex(&colors::parse_hex(&v[0])))),
                    background: Some(nm(&colors::to_hex(&colors::parse_hex(&v[1])))),
                    text: Some(nm(&colors::to_hex(&colors::parse_hex(&v[2])))),
                };
                match slot {
                    0 => t.bar.focused_workspace = Some(ws),
                    _ => t.bar.urgent_workspace = Some(ws),
                }
            }
        }
    }
    for (i, key) in config::CLIENT_KEYS.iter().enumerate() {
        if let Some(v) = get_client(key) {
            if v.len() >= 4 {
                let w = theme::WindowColors {
                    border: Some(nm(&colors::to_hex(&colors::parse_hex(&v[0])))),
                    background: Some(nm(&colors::to_hex(&colors::parse_hex(&v[1])))),
                    text: Some(nm(&colors::to_hex(&colors::parse_hex(&v[2])))),
                    indicator: Some(nm(&colors::to_hex(&colors::parse_hex(&v[3])))),
                };
                match i {
                    0 => t.focused = Some(w),
                    1 => t.focused_inactive = Some(w),
                    2 => t.unfocused = Some(w),
                    _ => t.urgent = Some(w),
                }
            }
        }
    }
    t
}
