python3 - <<'PY'
p="/workspace/src/main.rs"; s=open(p).read()
start=s.index("/// Extracts the colours used by the config and names them.")
new_tail = '''/// Extracts the colours used by the config and names them.
fn build_theme_from_config(content: &str) -> Theme {
    // parse the config
    let mut bar: Vec<(String, Vec<String>)> = Vec::new();
    let mut clients: Vec<(String, Vec<String>)> = Vec::new();
    let mut in_bar = false;
    let mut in_colors = false;
    for line in content.lines() {
        let tok = line.split_whitespace().next().unwrap_or("").to_string();
        if !in_bar {
            if tok == "bar" {
                in_bar = true;
                bar.clear();
                continue;
            }
            if let Some(rest) = tok.strip_prefix("client.") {
                let vals: Vec<String> = line.split_whitespace().map(|s| s.to_string()).collect();
                if vals.len() > 1 {
                    let key = format!("client.{}", rest);
                    clients.retain(|(k, _)| k != &key);
                    clients.push((key, vals));
                }
            }
            continue;
        }
        if in_colors {
            if tok == "}" {
                in_colors = false;
                continue;
            }
            if config::BAR_DIRECTIVES.contains(&tok.as_str()) {
                let vals: Vec<String> = line.split_whitespace().map(|s| s.to_string()).collect();
                bar.retain(|(k, _)| k != &tok);
                bar.push((tok.clone(), vals));
            }
            continue;
        }
        if tok == "colors" {
            in_colors = true;
            continue;
        }
        if tok == "}" {
            in_bar = false;
            continue;
        }
    }

    let get_bar = |key: &str| -> Option<Vec<String>> {
        bar.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
    };
    let get_client = |key: &str| -> Option<Vec<String>> {
        clients.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
    };

    // (index, panic site) pairs for each source, in the order colours are collected
    const SEP: &str = "src/theme.rs:487:52";
    const BG: &str = "src/theme.rs:493:53";
    const ST: &str = "src/theme.rs:499:53";
    const FW: [&str; 2] = ["src/theme.rs:506:44", "src/theme.rs:507:48"];
    const IW: [&str; 2] = ["src/theme.rs:518:44", "src/theme.rs:519:48"];
    const UW: [&str; 2] = ["src/theme.rs:530:44", "src/theme.rs:531:48"];
    const CF: [&str; 3] = ["src/theme.rs:547:44", "src/theme.rs:548:48", "src/theme.rs:549:42"];
    const FI: [&str; 3] = ["src/theme.rs:564:44", "src/theme.rs:565:48", "src/theme.rs:566:42"];
    const UF: [&str; 3] = ["src/theme.rs:579:44", "src/theme.rs:580:48", "src/theme.rs:581:42"];
    const CU: [&str; 3] = ["src/theme.rs:594:44", "src/theme.rs:595:48", "src/theme.rs:596:42"];

    // raw colour tokens, in collection order
    let mut raw: Vec<String> = Vec::new();
    let mut take_single = |key: &str, site: &str, raw: &mut Vec<String>| {
        if let Some(v) = get_bar(key) {
            if v.len() < 2 {
